CREATE FUNCTION pg_temp.rec(k text, v text) RETURNS void LANGUAGE sql AS $h$ INSERT INTO pg_temp.p4263a_out VALUES (k, v) $h$;

-- The state between 20261118110000 and this file: rows the one-way upserts inserted after the earlier
-- backfill (unnumbered), an item and a checklist removed by the one-way tombstone (scrubbed).
DO $setup$
DECLARE r jsonb;
BEGIN
  PERFORM pg_temp.rec('fixtures', pg_temp.base4263()::text);
  r := pg_temp.rpc(pg_temp.id('A'), format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[%L::uuid])', pg_temp.id('A'), pg_temp.id('I1'), 'checklist_item', pg_temp.id('i2')));
  PERFORM pg_temp.rec('setup_tomb_item', r::text);
  r := pg_temp.rpc(pg_temp.id('A'), format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[%L::uuid])', pg_temp.id('A'), pg_temp.id('I1'), 'checklist', pg_temp.id('cl2')));
  PERFORM pg_temp.rec('setup_tomb_checklist', r::text);
  -- removed through the NEW path before this file (the 4a build is already sending when it is applied):
  -- a checklist with an item, both created and then removed with cloud_todo_push; must NOT be purged
  r := pg_temp.push(pg_temp.id('A'), pg_temp.id('I1'), pg_temp.nowt(), jsonb_build_array(
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_checklist', 'deal_id', pg_temp.id('D1'), 'local_id', 'cl10',
      'template_id', 'tpl-10', 'template_name', 'Ten', 'sort_order', 10, 'is_private', false, 'edited_at', pg_temp.nowt()),
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_item', 'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl10',
      'local_id', 'i10', 'title', 'Ten a', 'done', false, 'edited_at', pg_temp.nowt()),
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_item', 'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl1',
      'local_id', 'i11', 'title', 'Eleven', 'done', false, 'edited_at', pg_temp.nowt())));
  PERFORM pg_temp.rec('setup_new_path_creates', r::text);
  r := pg_temp.push(pg_temp.id('A'), pg_temp.id('I1'), pg_temp.nowt(), jsonb_build_array(
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'remove', 'entity', 'item', 'deal_id', pg_temp.id('D1'), 'local_id', 'i11', 'edited_at', pg_temp.nowt()),
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'remove', 'entity', 'checklist', 'deal_id', pg_temp.id('D1'), 'local_id', 'cl10', 'edited_at', pg_temp.nowt())));
  PERFORM pg_temp.rec('setup_new_path_removes', r::text);
  CREATE TEMP TABLE p4263a_pre AS SELECT
    (SELECT count(*) FROM public.cloud_deal_checklist_items WHERE owner_user_id IN (pg_temp.id('A'), pg_temp.id('B')) AND change_seq IS NULL)
  + (SELECT count(*) FROM public.cloud_deal_checklists WHERE owner_user_id IN (pg_temp.id('A'), pg_temp.id('B')) AND change_seq IS NULL) AS unnumbered;
END $setup$;

-- ---------------------------------------------------------------- the migration under test
-- ============================================================================
-- Migration: two-way todos, the old one-way item path removed (BACKLOG-4263 PR-4a)
--
-- The desktop sends checklist and item changes through cloud_todo_push (migration 20261118110000) and no
-- longer calls the one-way checklist and item functions. This file:
--   1. numbers every row the one-way upserts inserted after 20261118110000 (change_seq NULL), with the same
--      allocator and the same part metadata that file's backfill wrote; post-check: no unnumbered row;
--   2. marks purged (purged_at, a new number) every checklist and item the one-way cloud_tombstone removed:
--      their content was scrubbed (items: title '[removed]', links '[]'; checklists: template_name NULL), so
--      they are not restorable; restore answers not_restorable and the removed lists leave them out;
--   3. drops cloud_upsert_checklists and cloud_upsert_checklist_items;
--   4. replaces cloud_tombstone and cloud_list_install_rows without their checklist and checklist_item kinds
--      (those kinds now answer invalid_input).
-- Kept on cloud_deal_checklists / _items: content_hash, version, links, origin and source_updated_at (still
--   read or written by 20261118110000's functions and by the replaced cloud_tombstone), and
--   last_change_request_id (read by no function; present on every cloud table, so not dropped from two).
-- Grants: unchanged for the two replaced functions (authenticated only); no function here is callable by anon.
-- Pre-check: each function this file drops or replaces is at the body 20261118110000 wrote (md5 of prosrc),
--   at this file's body, or (for the two dropped) already absent. Requires 20261118110000.
-- Lock order: as 20261118110000 (the owner's feed head through the allocator, then rows in id order).
-- Re-runnable. Rollback: supabase/tests/backlog-4263-pr4a/rollback-20261118120000.sql
-- ============================================================================

DO $precheck4263a$
DECLARE r record; v_md5 text; v_src text;
BEGIN
  IF to_regprocedure('public._cloud_todo_take_seq(uuid,integer)') IS NULL OR to_regprocedure('public.cloud_todo_push(uuid,uuid,text,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'BACKLOG-4263 PR-4a: migration 20261118110000 is not applied';
  END IF;
  FOR r IN SELECT * FROM (VALUES
      ('public.cloud_list_install_rows(uuid,uuid,text,uuid,integer)', 'e557b64992885fa2b3decff2f5b24781', true),
      ('public.cloud_tombstone(uuid,uuid,text,uuid[])', 'ac6e76a613b5aa10a0b95743c902c84c', true),
      ('public.cloud_upsert_checklist_items(uuid,uuid,uuid,jsonb)', '1bfb259e707b388a76610c26c26ce47e', false),
      ('public.cloud_upsert_checklists(uuid,uuid,uuid,jsonb)', '7ed9daf67e8b16258ab0b61dd26dfb4e', false)
    ) x(sig, md5, replaced) LOOP
    SELECT md5(p.prosrc), p.prosrc INTO v_md5, v_src FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS NULL AND NOT r.replaced THEN CONTINUE; END IF;
    IF v_md5 IS DISTINCT FROM r.md5 AND position('/*BODY:4263-4a*/' IN coalesce(v_src, '')) = 0 THEN
      RAISE EXCEPTION 'BACKLOG-4263 PR-4a: % is not at the traced body (md5 %)', r.sig, coalesce(v_md5, 'missing');
    END IF;
  END LOOP;
END
$precheck4263a$;

-- ============================================================================ 1. numbers and part metadata
DO $backfill4263a$
DECLARE o uuid; n integer; s bigint[];
BEGIN
  FOR o IN SELECT x.owner_user_id FROM (
             SELECT owner_user_id FROM public.cloud_deals WHERE change_seq IS NULL
             UNION SELECT owner_user_id FROM public.cloud_deal_checklists WHERE change_seq IS NULL
             UNION SELECT owner_user_id FROM public.cloud_deal_checklist_items WHERE change_seq IS NULL) x
            ORDER BY 1 LOOP
    SELECT count(*) INTO n FROM public.cloud_deals WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deals d SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deals x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE d.id = r.id;
    END IF;
    SELECT count(*) INTO n FROM public.cloud_deal_checklists WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deal_checklists c SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deal_checklists x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE c.id = r.id;
    END IF;
    SELECT count(*) INTO n FROM public.cloud_deal_checklist_items WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deal_checklist_items t SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deal_checklist_items x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE t.id = r.id;
    END IF;
  END LOOP;
  UPDATE public.cloud_deal_checklists c
     SET created_by_kind = 'desktop', created_by_ref = d.source_install_id::text,
         order_eff_at = coalesce(c.source_updated_at, c.updated_at), order_by = 'desktop:' || d.source_install_id::text,
         removed_eff_at = c.removed_at, removed_by = CASE WHEN c.removed_at IS NOT NULL THEN 'desktop:' || d.source_install_id::text END,
         removed_kind = CASE WHEN c.removed_at IS NOT NULL THEN 'checklist' END
    FROM public.cloud_deals d
   WHERE d.id = c.cloud_deal_id AND c.created_by_kind IS NULL;
  UPDATE public.cloud_deal_checklist_items t
     SET created_by_kind = 'desktop', created_by_ref = d.source_install_id::text,
         done_eff_at = coalesce(t.source_updated_at, t.updated_at), done_by = 'desktop:' || d.source_install_id::text,
         title_eff_at = coalesce(t.source_updated_at, t.updated_at), title_by = 'desktop:' || d.source_install_id::text,
         note_eff_at = coalesce(t.source_updated_at, t.updated_at), note_by = 'desktop:' || d.source_install_id::text,
         due_eff_at = coalesce(t.source_updated_at, t.updated_at), due_by = 'desktop:' || d.source_install_id::text,
         order_eff_at = coalesce(t.source_updated_at, t.updated_at), order_by = 'desktop:' || d.source_install_id::text,
         removed_eff_at = t.removed_at, removed_by = CASE WHEN t.removed_at IS NOT NULL THEN 'desktop:' || d.source_install_id::text END,
         removed_kind = CASE WHEN t.removed_at IS NOT NULL THEN 'item' END
    FROM public.cloud_deals d
   WHERE d.id = t.cloud_deal_id AND t.created_by_kind IS NULL;
  IF ((SELECT count(*) FROM public.cloud_deals WHERE change_seq IS NULL)
         + (SELECT count(*) FROM public.cloud_deal_checklists WHERE change_seq IS NULL)
         + (SELECT count(*) FROM public.cloud_deal_checklist_items WHERE change_seq IS NULL)) <> 0 THEN
    RAISE EXCEPTION 'BACKLOG-4263 PR-4a: unnumbered rows remain';
  END IF;
END
$backfill4263a$;

-- ============================================================================ 2. rows the one-way tombstone scrubbed
-- Their signature: removed, not purged, and scrubbed the way only the one-way cloud_tombstone scrubbed
-- (items: links '[]', written by no other function except the purge, which also sets purged_at; checklists:
-- template_name NULL, which neither the desktop create nor the AI-app My items create writes).
DO $scrubbed4263a$
DECLARE v_id uuid; v_owner uuid;
BEGIN
  FOR v_id, v_owner IN SELECT t.id, t.owner_user_id FROM public.cloud_deal_checklist_items t
                        WHERE t.removed_at IS NOT NULL AND t.purged_at IS NULL AND t.links = '[]'::jsonb      /*SCRUB:items*/
                        ORDER BY t.owner_user_id, t.id LOOP
    UPDATE public.cloud_deal_checklist_items SET purged_at = now(), change_seq = (public._cloud_todo_take_seq(v_owner, 1))[1]
     WHERE id = v_id;
  END LOOP;
  FOR v_id, v_owner IN SELECT c.id, c.owner_user_id FROM public.cloud_deal_checklists c
                        WHERE c.removed_at IS NOT NULL AND c.purged_at IS NULL AND c.template_name IS NULL     /*SCRUB:checklists*/
                        ORDER BY c.owner_user_id, c.id LOOP
    UPDATE public.cloud_deal_checklists SET purged_at = now(), change_seq = (public._cloud_todo_take_seq(v_owner, 1))[1]
     WHERE id = v_id;
  END LOOP;
END
$scrubbed4263a$;

-- ============================================================================ 3. the one-way checklist and item upserts
DROP FUNCTION IF EXISTS public.cloud_upsert_checklists(uuid, uuid, uuid, jsonb);
DROP FUNCTION IF EXISTS public.cloud_upsert_checklist_items(uuid, uuid, uuid, jsonb);

-- ============================================================================ 4. replaced without the checklist kinds
CREATE OR REPLACE FUNCTION public.cloud_tombstone(p_expected_user_id uuid, p_source_install_id uuid, p_kind text, p_cloud_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $f$
/*BODY:4263-4a*/
DECLARE v_uid uuid := auth.uid(); v_tab text; v_id uuid; out jsonb := '[]'::jsonb;
        v_row_id uuid; v_row_deal uuid; v_row_removed timestamptz; v_row_version bigint; v_blob uuid; v_deals uuid[];
        v_fence uuid[] := '{}'; v_now timestamptz;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authorized'); END IF;
  IF p_expected_user_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'wrong_account'); END IF;   /*WHO:tombstone*/
  -- checklists and items are todo changes (cloud_todo_push) since 20261118120000: no arm for them here
  v_tab := CASE p_kind WHEN 'party' THEN 'cloud_deal_parties' WHEN 'message' THEN 'cloud_deal_messages'
                       WHEN 'file' THEN 'cloud_deal_files' END;
  IF v_tab IS NULL OR p_source_install_id IS NULL OR p_cloud_ids IS NULL OR cardinality(p_cloud_ids) > 1000 THEN   /*CAP:tombstone*/
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_input');
  END IF;
  PERFORM 1 FROM public.cloud_autosave_settings WHERE user_id = v_uid FOR SHARE;
  IF public._cloud_install_removed(v_uid, p_source_install_id) THEN                       /*GATE:install:tombstone*/
    RETURN jsonb_build_object('ok', false, 'error', 'install_removed');
  END IF;
  EXECUTE format(
    'SELECT array_agg(x.id) FROM (SELECT d.id FROM public.cloud_deals d
       WHERE d.owner_user_id = $1 AND d.source_install_id = $2
         AND d.id IN (SELECT t.cloud_deal_id FROM public.%I t WHERE t.id = ANY ($3) AND t.owner_user_id = $1)
       ORDER BY d.id FOR NO KEY UPDATE) x', v_tab)
    INTO v_deals USING v_uid, p_source_install_id, p_cloud_ids;                              /*TOMB:lockdeals*/
  v_now := clock_timestamp();                                                                /*CLOCK:tombstone*/
  FOREACH v_id IN ARRAY p_cloud_ids LOOP
    v_row_id := NULL;
    EXECUTE format(
      'SELECT t.id, t.cloud_deal_id, t.removed_at, t.version FROM public.%I t
         JOIN public.cloud_deals d ON d.id = t.cloud_deal_id
        WHERE t.id = $1 AND t.owner_user_id = $2 /*OWNER:tombstone*/
          AND d.source_install_id = $3 /*INSTALL:tombstone*/
        FOR UPDATE OF t', v_tab)
      INTO v_row_id, v_row_deal, v_row_removed, v_row_version USING v_id, v_uid, p_source_install_id;
    IF v_row_id IS NULL THEN
      out := out || jsonb_build_object('cloud_id', v_id, 'status', 'not_found');
      CONTINUE;
    END IF;
    IF v_row_removed IS NOT NULL THEN
      out := out || jsonb_build_object('cloud_id', v_id, 'status', 'unchanged', 'version', v_row_version);
      CONTINUE;
    END IF;
    IF p_kind = 'party' THEN
      UPDATE public.cloud_deal_parties SET removed_at = now(), version = version + 1, updated_at = now(),
             display_name = NULL, company = NULL, emails = NULL, phones = NULL, notes = NULL
       WHERE id = v_row_id RETURNING version INTO v_row_version;
    ELSIF p_kind = 'message' THEN
      UPDATE public.cloud_deal_messages SET removed_at = now(), version = version + 1, updated_at = now(),
             subject = NULL, body_text = NULL, body_truncated = false, participants = NULL          /*TOMB:scrub*/
       WHERE id = v_row_id RETURNING version INTO v_row_version;
    ELSE
      SELECT f.blob_id INTO v_blob FROM public.cloud_deal_files f WHERE f.id = v_row_id;
      UPDATE public.cloud_deal_files f SET removed_at = now(), version = version + 1, updated_at = now(),
             filename = NULL, blob_id = NULL
       WHERE f.id = v_row_id RETURNING f.version INTO v_row_version;
      v_fence := v_fence || v_blob;
    END IF;
    UPDATE public.cloud_deals SET last_synced_at = greatest(last_synced_at, v_now) WHERE id = v_row_deal;
    out := out || jsonb_build_object('cloud_id', v_id, 'status', 'removed', 'version', v_row_version);
  END LOOP;
  PERFORM public._cloud_fence_unreferenced(v_uid, v_fence);                                  /*TOMB:fence*/
  RETURN jsonb_build_object('ok', true, 'results', out);
END $f$;
REVOKE ALL ON FUNCTION public.cloud_tombstone(uuid, uuid, text, uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.cloud_tombstone(uuid, uuid, text, uuid[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.cloud_list_install_rows(
  p_expected_user_id uuid, p_source_install_id uuid, p_kind text, p_after uuid, p_limit integer
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $f$
/*BODY:4263-4a*/
DECLARE v_uid uuid := auth.uid(); v_limit integer; v_tab text; v_local text; v_deal text; v_removed text;
        v_rows jsonb; v_n integer; v_last uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authorized'); END IF;
  IF p_expected_user_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'wrong_account'); END IF;   /*WHO:list_rows*/
  IF p_source_install_id IS NULL OR p_kind IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_input'); END IF;
  SELECT k.tab, k.local_col, k.deal_col, k.removed_expr INTO v_tab, v_local, v_deal, v_removed
    FROM (VALUES
      ('deal',           'cloud_deals',                'local_transaction_id', 't.id',            't.removed_at IS NOT NULL'),
      ('party',          'cloud_deal_parties',         'local_party_id',       't.cloud_deal_id', 't.removed_at IS NOT NULL OR d.removed_at IS NOT NULL')
    ) k(kind, tab, local_col, deal_col, removed_expr)                                          -- no checklist kinds since 20261118120000                                           /*LIVE:list_rows*/
   WHERE k.kind = p_kind;
  IF v_tab IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_input'); END IF;
  v_limit := least(greatest(coalesce(p_limit, 1000), 1), 1000);                               /*CAP:list_rows*/
  EXECUTE format(
    'SELECT coalesce(jsonb_agg(jsonb_build_object(''cloud_id'', x.id, ''cloud_deal_id'', x.deal_id, ''local_id'', x.local_id,
                                                   ''content_hash'', x.content_hash, ''removed'', x.removed) ORDER BY x.id), ''[]''::jsonb),
            count(*)::integer, (array_agg(x.id ORDER BY x.id DESC))[1]
       FROM (SELECT t.id, %s AS deal_id, t.%I AS local_id, t.content_hash, (%s) AS removed
               FROM public.%I t JOIN public.cloud_deals d ON d.id = %s
              WHERE t.owner_user_id = $1 AND d.owner_user_id = $1 /*OWNER:list_rows*/
                AND d.source_install_id = $2 /*INSTALL:list_rows*/
                AND ($3 IS NULL OR t.id > $3)
              ORDER BY t.id LIMIT $4) x',
    v_deal, v_local, v_removed, v_tab, v_deal)
    INTO v_rows, v_n, v_last USING v_uid, p_source_install_id, p_after, v_limit;
  RETURN jsonb_build_object('ok', true, 'rows', v_rows,
                            'next_after', CASE WHEN v_n = v_limit THEN v_last END);
END $f$;
REVOKE ALL ON FUNCTION public.cloud_list_install_rows(uuid, uuid, text, uuid, integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.cloud_list_install_rows(uuid, uuid, text, uuid, integer) TO authenticated;


DO $controls$
DECLARE A uuid := pg_temp.id('A'); I1 uuid := pg_temp.id('I1'); r jsonb; r8 jsonb; t text; v_ops jsonb; s text;
BEGIN
  -- C1 backfill: there were unnumbered fixture rows; none is left; each has its part metadata
  PERFORM pg_temp.rec('C1_backfill', pg_temp.all_of(
    pg_temp.pass((SELECT unnumbered FROM pg_temp.p4263a_pre) > 0, 'fixtures had no unnumbered row (the case is not exercised)'),
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklist_items WHERE change_seq IS NULL) + (SELECT count(*) FROM public.cloud_deal_checklists WHERE change_seq IS NULL)
                 + (SELECT count(*) FROM public.cloud_deals WHERE change_seq IS NULL) = 0, 'unnumbered rows left'),
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklist_items WHERE owner_user_id = A AND (created_by_kind IS NULL OR done_by IS NULL)) = 0, 'item metadata missing'),
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklists WHERE owner_user_id = A AND (created_by_kind IS NULL OR order_by IS NULL)) = 0, 'checklist metadata missing'),
    pg_temp.pass((SELECT max(change_seq) FROM public.cloud_deal_checklist_items WHERE owner_user_id = A) <= pg_temp.head(A), 'numbers above the head')));
  -- C2 numbered rows reach a full pull
  r := pg_temp.pull_all(A, I1, 0, 500);
  PERFORM pg_temp.rec('C2_pull', pg_temp.pass((r -> 'ids') ? pg_temp.id('i1')::text AND (r -> 'ids') ? pg_temp.id('m1')::text, r::text));
  -- C3 scrubbed rows are purged: restore answers not_restorable, the removed list leaves them out
  PERFORM pg_temp.rec('C3_scrubbed', pg_temp.all_of(
    pg_temp.pass((pg_temp.it(pg_temp.id('i2'))).purged_at IS NOT NULL AND (pg_temp.it(pg_temp.id('i2'))).change_seq IS NOT NULL, 'i2 not purged'),
    pg_temp.pass((SELECT purged_at IS NOT NULL FROM public.cloud_deal_checklists WHERE id = pg_temp.id('cl2')), 'cl2 not purged'),
    pg_temp.pass((pg_temp.it(pg_temp.id('i3'))).purged_at IS NOT NULL, 'i3 (scrubbed with cl2) not purged'),
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_todo_restore(%L::uuid, %L, %L::uuid)', A, 'item', pg_temp.id('i2'))) -> 'results' -> 0 ->> 'status' = 'not_restorable',
                 pg_temp.rpc(A, format('SELECT public.cloud_todo_restore(%L::uuid, %L, %L::uuid)', A, 'item', pg_temp.id('i2')))::text),
    pg_temp.pass(position(pg_temp.id('i2')::text IN pg_temp.rpc(A, format('SELECT public.cloud_list_removed(%L::uuid)', A))::text) = 0, 'i2 listed as removed'),
    pg_temp.pass((pg_temp.it(pg_temp.id('i1'))).purged_at IS NULL AND (pg_temp.it(pg_temp.id('m1'))).purged_at IS NULL, 'a live item was purged'),
    -- removed through the new path: still restorable (not purged), still listed
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklist_items WHERE owner_user_id = A AND local_item_id IN ('i10', 'i11') AND purged_at IS NULL) = 2
                 AND (SELECT count(*) FROM public.cloud_deal_checklists WHERE owner_user_id = A AND local_checklist_id = 'cl10' AND removed_at IS NOT NULL AND purged_at IS NULL) = 1,
                 'a new-path removal was purged'),
    pg_temp.pass(position('Eleven' IN pg_temp.rpc(A, format('SELECT public.cloud_list_removed(%L::uuid)', A))::text) > 0, 'new-path removed item not listed')));
  -- C4 the two upserts are gone; an old build's call fails (42883 here; PostgREST answers PGRST202 / 404)
  t := pg_temp.call_as(A, format('SELECT public.cloud_upsert_checklist_items(%L::uuid, %L::uuid, %L::uuid, %L::jsonb)', A, I1, pg_temp.id('D1'), '[]'));
  PERFORM pg_temp.rec('C4_dropped', pg_temp.all_of(
    pg_temp.pass(to_regprocedure('public.cloud_upsert_checklists(uuid,uuid,uuid,jsonb)') IS NULL AND to_regprocedure('public.cloud_upsert_checklist_items(uuid,uuid,uuid,jsonb)') IS NULL, 'still present'),
    pg_temp.pass(t LIKE 'ERR 42883%', t)));
  -- C5 cloud_tombstone: checklist kinds answer invalid_input; party still removes
  PERFORM pg_temp.rec('C5_tombstone', pg_temp.all_of(
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[%L::uuid])', A, I1, 'checklist_item', pg_temp.id('i1'))) ->> 'error' = 'invalid_input', 'item kind'),
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[%L::uuid])', A, I1, 'checklist', pg_temp.id('cl1'))) ->> 'error' = 'invalid_input', 'checklist kind'),
    pg_temp.pass((pg_temp.it(pg_temp.id('i1'))).removed_at IS NULL, 'i1 removed by the refused call'),
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[gen_random_uuid()])', A, I1, 'party')) ->> 'ok' = 'true', 'party kind refused')));
  -- C6 cloud_list_install_rows: checklist kinds answer invalid_input; deal and party still list
  PERFORM pg_temp.rec('C6_list_rows', pg_temp.all_of(
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_list_install_rows(%L::uuid, %L::uuid, %L, NULL, 10)', A, I1, 'checklist_item')) ->> 'error' = 'invalid_input', 'item kind'),
    pg_temp.pass(pg_temp.rpc(A, format('SELECT public.cloud_list_install_rows(%L::uuid, %L::uuid, %L, NULL, 10)', A, I1, 'checklist')) ->> 'error' = 'invalid_input', 'checklist kind'),
    pg_temp.pass(jsonb_array_length(pg_temp.rpc(A, format('SELECT public.cloud_list_install_rows(%L::uuid, %L::uuid, %L, NULL, 10)', A, I1, 'deal')) -> 'rows') = 2, 'deal rows')));
  -- C7 grants: the replaced functions are authenticated only; anon is refused
  PERFORM pg_temp.rec('C7_grants', pg_temp.all_of(
    pg_temp.pass(NOT has_function_privilege('anon', 'public.cloud_tombstone(uuid,uuid,text,uuid[])', 'EXECUTE') AND has_function_privilege('authenticated', 'public.cloud_tombstone(uuid,uuid,text,uuid[])', 'EXECUTE'), 'tombstone grants'),
    pg_temp.pass(NOT has_function_privilege('anon', 'public.cloud_list_install_rows(uuid,uuid,text,uuid,integer)', 'EXECUTE'), 'list rows grants'),
    pg_temp.pass(pg_temp.call_as(NULL, format('SELECT public.cloud_tombstone(%L::uuid, %L::uuid, %L, ARRAY[]::uuid[])', A, I1, 'party'), 'anon') LIKE 'ERR 42501%', 'anon reached tombstone')));
  -- C8 the desktop sender's ops, as todos/wire.ts encodes them (shapes from cloudSyncTodoSend-4263.test.ts):
  --    every answer the fake server gives is re-checked here against the applied functions
  v_ops := jsonb_build_array(
    jsonb_build_object('op_id', pg_temp.opid(1), 'kind', 'create_checklist', 'edited_at', pg_temp.nowt('-1 minute'), 'clock_stepped', false,
      'deal_id', pg_temp.id('D1'), 'local_id', 'cl9', 'template_id', 'tpl-9', 'template_name', 'Nine', 'sort_order', 9, 'is_private', false),
    jsonb_build_object('op_id', pg_temp.opid(2), 'kind', 'create_item', 'edited_at', pg_temp.nowt('-1 minute'), 'clock_stepped', false,
      'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl9', 'local_id', 'i9', 'title', 'Nine a', 'description', NULL, 'is_required', true,
      'expected_document_type', 'other', 'local_created_at', pg_temp.nowt('-2 minutes'), 'done', jsonb_build_object('is_checked', false, 'checked_at', NULL),
      'note', NULL, 'due_date', NULL, 'sort_order', 0, 'edit_seq', 1),
    jsonb_build_object('op_id', pg_temp.opid(3), 'kind', 'set', 'edited_at', pg_temp.nowt('-30 seconds'), 'clock_stepped', false,
      'entity', 'item', 'deal_id', pg_temp.id('D1'), 'local_id', 'i9', 'part', 'note', 'value', 'booked', 'base_rev', 1, 'edit_seq', 2),
    jsonb_build_object('op_id', pg_temp.opid(4), 'kind', 'create_item', 'edited_at', pg_temp.nowt(), 'clock_stepped', true,
      'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl1', 'local_id', 'i1', 'title', 'Inspection report', 'description', NULL, 'is_required', true,
      'expected_document_type', NULL, 'local_created_at', NULL, 'done', jsonb_build_object('is_checked', true, 'checked_at', pg_temp.nowt()),
      'note', NULL, 'due_date', NULL, 'sort_order', 1, 'edit_seq', 3),
    jsonb_build_object('op_id', pg_temp.opid(5), 'kind', 'remove', 'edited_at', pg_temp.nowt(), 'clock_stepped', false,
      'entity', 'item', 'deal_id', pg_temp.id('D1'), 'local_id', 'i9'),
    jsonb_build_object('op_id', pg_temp.opid(6), 'kind', 'set', 'edited_at', pg_temp.nowt(), 'clock_stepped', false,
      'entity', 'item', 'deal_id', pg_temp.id('D1'), 'local_id', 'no-such-item', 'part', 'note', 'value', 'x', 'base_rev', NULL, 'edit_seq', 4));
  r := pg_temp.push(A, I1, pg_temp.nowt(), v_ops);
  PERFORM pg_temp.rec('C8_answers', r::text);
  r8 := r;
  PERFORM pg_temp.rec('C8_desktop_ops', pg_temp.all_of(
    pg_temp.pass(pg_temp.st(r, 0) = 'added' AND pg_temp.st(r, 1) = 'added' AND pg_temp.st(r, 2) = 'applied', r::text),
    pg_temp.pass(pg_temp.st(r, 3) = 'exists', 'existing item: ' || pg_temp.st(r, 3)),
    pg_temp.pass(pg_temp.st(r, 4) = 'removed' AND pg_temp.st(r, 5) = 'not_found', 'remove / not_found'),
    pg_temp.pass(r -> 'results' -> 0 ->> 'op_id' = pg_temp.opid(1)::text, 'op_id echo form'),
    pg_temp.pass(jsonb_typeof(r -> 'results' -> 2 -> 'parts' -> 'note' -> 'rev') = 'number' AND r -> 'results' -> 2 -> 'parts' -> 'note' ->> 'value' = 'booked', 'parts shape'),
    pg_temp.pass(r -> 'results' -> 1 -> 'parts' -> 'done' -> 'value' ? 'is_checked', 'done value shape')));
  -- C8b My items (contract my_items @ 00bd934db): a second local My items list maps to the live one, items name it by
  --     the desktop's own local id; a remove of a My items list is not_allowed for the desktop too
  r := pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(
    jsonb_build_object('op_id', pg_temp.opid(21), 'kind', 'create_checklist', 'edited_at', pg_temp.nowt(), 'clock_stepped', true,
      'deal_id', pg_temp.id('D1'), 'local_id', 'my-desk-2', 'template_id', 'keepr:my-items', 'template_name', 'My items', 'sort_order', 1, 'is_private', true),
    jsonb_build_object('op_id', pg_temp.opid(22), 'kind', 'create_item', 'edited_at', pg_temp.nowt(), 'clock_stepped', true,
      'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'my-desk-2', 'local_id', 'i-my-2', 'title', 'Under the mapped list', 'description', NULL,
      'is_required', NULL, 'expected_document_type', NULL, 'local_created_at', NULL, 'done', jsonb_build_object('is_checked', false, 'checked_at', NULL),
      'note', NULL, 'due_date', NULL, 'sort_order', 0, 'edit_seq', NULL),
    jsonb_build_object('op_id', pg_temp.opid(23), 'kind', 'remove', 'edited_at', pg_temp.nowt(), 'clock_stepped', false,
      'entity', 'checklist', 'deal_id', pg_temp.id('D1'), 'local_id', 'my-desk-2')));
  PERFORM pg_temp.rec('C8b_answers', r::text);
  PERFORM pg_temp.rec('C8b_my_items', pg_temp.all_of(
    pg_temp.pass(pg_temp.st(r, 0) = 'mapped' AND r -> 'results' -> 0 ->> 'cloud_id' = pg_temp.id('my1')::text, 'mapped: ' || pg_temp.st(r, 0)),
    pg_temp.pass(pg_temp.st(r, 1) = 'added', 'item under the mapped list: ' || pg_temp.st(r, 1)),
    pg_temp.pass(pg_temp.st(r, 2) = 'not_allowed', 'My items remove: ' || pg_temp.st(r, 2)),
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklists WHERE cloud_deal_id = pg_temp.id('D1') AND template_id = 'keepr:my-items') = 1, 'a second list')));
  -- C9 a replay of the same op_ids: kept answers replay exactly; not_found is evaluated again
  r := pg_temp.push(A, I1, pg_temp.nowt(), v_ops);
  PERFORM pg_temp.rec('C9_replay', pg_temp.all_of(
    pg_temp.pass((r -> 'results' -> 2) = (r8 -> 'results' -> 2), 'replay differs: ' || (r -> 'results' -> 2)::text),
    pg_temp.pass(pg_temp.st(r, 5) = 'not_found', 'not_found re-evaluated: ' || pg_temp.st(r, 5))));
  -- C10 the raw (unconverted) shapes PR-3's outbox holds are refused per op, as the desktop must never send them
  r := pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'set', 'entity', 'item', 'deal_id', pg_temp.id('D1'), 'local_id', 'i1', 'part', 'title', 'value', jsonb_build_object('title', 'x'), 'edited_at', pg_temp.nowt()),
    jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_item', 'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl1', 'local_id', 'raw', 'title', 'Raw', 'is_required', 1, 'edited_at', pg_temp.nowt())));
  PERFORM pg_temp.rec('C10_raw_refused', pg_temp.pass(pg_temp.st(r, 0) = 'rejected' AND pg_temp.st(r, 1) = 'rejected', r::text));
  -- C13 (SR re-check d) a set on a row this file marked purged answers not_restorable (final)
  r := pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'set', 'entity', 'item',
         'deal_id', pg_temp.id('D1'), 'local_id', 'i2', 'part', 'note', 'value', 'x', 'base_rev', NULL, 'edit_seq', NULL, 'edited_at', pg_temp.nowt(), 'clock_stepped', false)));
  PERFORM pg_temp.rec('C13_purged_not_restorable', pg_temp.pass(pg_temp.st(r, 0) = 'not_restorable', r::text));
  -- C14 (SR re-check f) parent_missing is evaluated again with the same op_id once the parent exists
  v_ops := jsonb_build_array(jsonb_build_object('op_id', pg_temp.opid(31), 'kind', 'create_item', 'edited_at', pg_temp.nowt(), 'clock_stepped', false,
      'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'cl-later', 'local_id', 'i-later', 'title', 'Later', 'done', false, 'edit_seq', NULL));
  t := pg_temp.st(pg_temp.push(A, I1, pg_temp.nowt(), v_ops), 0);
  PERFORM pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_checklist', 'edited_at', pg_temp.nowt(),
      'clock_stepped', false, 'deal_id', pg_temp.id('D1'), 'local_id', 'cl-later', 'template_id', 'tpl-later', 'template_name', 'Later', 'sort_order', 20, 'is_private', false)));
  s := pg_temp.st(pg_temp.push(A, I1, pg_temp.nowt(), v_ops), 0);
  PERFORM pg_temp.rec('C14_parent_missing_again', pg_temp.pass(t = 'rejected' AND s = 'added', t || ' then ' || s));
  -- C15 (SR re-check a, b) the initial scan's create for old-path todos: exists, no duplicate; a part another actor
  --     changed first is kept (the unknowable create loses) and its value comes back in the answer
  PERFORM pg_temp.ai(A, jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'set', 'entity', 'item', 'id', pg_temp.id('m1'), 'part', 'note', 'value', 'from the AI app')));
  r := pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'create_item', 'edited_at', pg_temp.nowt(), 'clock_stepped', true,
      'deal_id', pg_temp.id('D1'), 'checklist_local_id', 'my1', 'local_id', 'm1', 'title', 'Call lender', 'description', NULL, 'is_required', NULL,
      'expected_document_type', NULL, 'local_created_at', NULL, 'done', jsonb_build_object('is_checked', false, 'checked_at', NULL),
      'note', 'stale local note', 'due_date', NULL, 'sort_order', 1, 'edit_seq', 900)));
  PERFORM pg_temp.rec('C15_answer', r::text);
  PERFORM pg_temp.rec('C15_scan_create_existing', pg_temp.all_of(
    pg_temp.pass(pg_temp.st(r, 0) = 'exists', pg_temp.st(r, 0)),
    pg_temp.pass(r -> 'results' -> 0 -> 'parts' -> 'note' ->> 'value' = 'from the AI app', 'note returned: ' || coalesce(r -> 'results' -> 0 -> 'parts' -> 'note' ->> 'value', 'null')),
    pg_temp.pass((SELECT count(*) FROM public.cloud_deal_checklist_items WHERE cloud_deal_id = pg_temp.id('D1') AND local_item_id = 'm1') = 1, 'duplicated')));
  -- C16 (SR re-check c) a deal deleted online, then uploaded again by its install: the same id, its todos answer as live
  PERFORM pg_temp.deldeal(A, pg_temp.id('D1'));
  r := pg_temp.deal(A, pg_temp.dp(I1, 'd1', '{"property_city":"again"}'));
  t := r -> 'results' -> 0 ->> 'cloud_id';
  r := pg_temp.push(A, I1, pg_temp.nowt(), jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'set', 'entity', 'item',
         'deal_id', pg_temp.id('D1'), 'local_id', 'i1', 'part', 'note', 'value', 'after the re-upload', 'base_rev', NULL, 'edit_seq', 901, 'edited_at', pg_temp.nowt(), 'clock_stepped', false)));
  PERFORM pg_temp.rec('C16_answer', r::text);
  PERFORM pg_temp.rec('C16_deal_reupload', pg_temp.all_of(
    pg_temp.pass(t = pg_temp.id('D1')::text, 'new id ' || coalesce(t, 'null')),
    pg_temp.pass(pg_temp.st(r, 0) IN ('applied', 'unchanged'), pg_temp.st(r, 0))));
  -- C11 install_removed: a registered install's push is refused as a whole
  PERFORM pg_temp.delinst(A, pg_temp.id('I2'));
  r := pg_temp.push(A, pg_temp.id('I2'), pg_temp.nowt(), jsonb_build_array(jsonb_build_object('op_id', gen_random_uuid(), 'kind', 'remove', 'entity', 'item', 'deal_id', pg_temp.id('D3'), 'local_id', 'i4', 'edited_at', pg_temp.nowt())));
  PERFORM pg_temp.rec('C11_install_removed', pg_temp.pass(r ->> 'error' = 'install_removed', r::text));
END $controls$;

-- C12 re-run: the file runs again with no change
CREATE TEMP TABLE p4263a_md5 AS SELECT p.oid::regprocedure::text AS sig, md5(p.prosrc) AS m FROM pg_proc p
 WHERE p.oid IN (to_regprocedure('public.cloud_tombstone(uuid,uuid,text,uuid[])'), to_regprocedure('public.cloud_list_install_rows(uuid,uuid,text,uuid,integer)'));
-- ============================================================================
-- Migration: two-way todos, the old one-way item path removed (BACKLOG-4263 PR-4a)
--
-- The desktop sends checklist and item changes through cloud_todo_push (migration 20261118110000) and no
-- longer calls the one-way checklist and item functions. This file:
--   1. numbers every row the one-way upserts inserted after 20261118110000 (change_seq NULL), with the same
--      allocator and the same part metadata that file's backfill wrote; post-check: no unnumbered row;
--   2. marks purged (purged_at, a new number) every checklist and item the one-way cloud_tombstone removed:
--      their content was scrubbed (items: title '[removed]', links '[]'; checklists: template_name NULL), so
--      they are not restorable; restore answers not_restorable and the removed lists leave them out;
--   3. drops cloud_upsert_checklists and cloud_upsert_checklist_items;
--   4. replaces cloud_tombstone and cloud_list_install_rows without their checklist and checklist_item kinds
--      (those kinds now answer invalid_input).
-- Kept on cloud_deal_checklists / _items: content_hash, version, links, origin and source_updated_at (still
--   read or written by 20261118110000's functions and by the replaced cloud_tombstone), and
--   last_change_request_id (read by no function; present on every cloud table, so not dropped from two).
-- Grants: unchanged for the two replaced functions (authenticated only); no function here is callable by anon.
-- Pre-check: each function this file drops or replaces is at the body 20261118110000 wrote (md5 of prosrc),
--   at this file's body, or (for the two dropped) already absent. Requires 20261118110000.
-- Lock order: as 20261118110000 (the owner's feed head through the allocator, then rows in id order).
-- Re-runnable. Rollback: supabase/tests/backlog-4263-pr4a/rollback-20261118120000.sql
-- ============================================================================

DO $precheck4263a$
DECLARE r record; v_md5 text; v_src text;
BEGIN
  IF to_regprocedure('public._cloud_todo_take_seq(uuid,integer)') IS NULL OR to_regprocedure('public.cloud_todo_push(uuid,uuid,text,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'BACKLOG-4263 PR-4a: migration 20261118110000 is not applied';
  END IF;
  FOR r IN SELECT * FROM (VALUES
      ('public.cloud_list_install_rows(uuid,uuid,text,uuid,integer)', 'e557b64992885fa2b3decff2f5b24781', true),
      ('public.cloud_tombstone(uuid,uuid,text,uuid[])', 'ac6e76a613b5aa10a0b95743c902c84c', true),
      ('public.cloud_upsert_checklist_items(uuid,uuid,uuid,jsonb)', '1bfb259e707b388a76610c26c26ce47e', false),
      ('public.cloud_upsert_checklists(uuid,uuid,uuid,jsonb)', '7ed9daf67e8b16258ab0b61dd26dfb4e', false)
    ) x(sig, md5, replaced) LOOP
    SELECT md5(p.prosrc), p.prosrc INTO v_md5, v_src FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS NULL AND NOT r.replaced THEN CONTINUE; END IF;
    IF v_md5 IS DISTINCT FROM r.md5 AND position('/*BODY:4263-4a*/' IN coalesce(v_src, '')) = 0 THEN
      RAISE EXCEPTION 'BACKLOG-4263 PR-4a: % is not at the traced body (md5 %)', r.sig, coalesce(v_md5, 'missing');
    END IF;
  END LOOP;
END
$precheck4263a$;

-- ============================================================================ 1. numbers and part metadata
DO $backfill4263a$
DECLARE o uuid; n integer; s bigint[];
BEGIN
  FOR o IN SELECT x.owner_user_id FROM (
             SELECT owner_user_id FROM public.cloud_deals WHERE change_seq IS NULL
             UNION SELECT owner_user_id FROM public.cloud_deal_checklists WHERE change_seq IS NULL
             UNION SELECT owner_user_id FROM public.cloud_deal_checklist_items WHERE change_seq IS NULL) x
            ORDER BY 1 LOOP
    SELECT count(*) INTO n FROM public.cloud_deals WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deals d SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deals x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE d.id = r.id;
    END IF;
    SELECT count(*) INTO n FROM public.cloud_deal_checklists WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deal_checklists c SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deal_checklists x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE c.id = r.id;
    END IF;
    SELECT count(*) INTO n FROM public.cloud_deal_checklist_items WHERE owner_user_id = o AND change_seq IS NULL;
    IF n > 0 THEN
      s := public._cloud_todo_take_seq(o, n);
      UPDATE public.cloud_deal_checklist_items t SET change_seq = s[r.rn]
        FROM (SELECT x.id, row_number() OVER (ORDER BY x.id) AS rn FROM public.cloud_deal_checklist_items x
               WHERE x.owner_user_id = o AND x.change_seq IS NULL) r
       WHERE t.id = r.id;
    END IF;
  END LOOP;
  UPDATE public.cloud_deal_checklists c
     SET created_by_kind = 'desktop', created_by_ref = d.source_install_id::text,
         order_eff_at = coalesce(c.source_updated_at, c.updated_at), order_by = 'desktop:' || d.source_install_id::text,
         removed_eff_at = c.removed_at, removed_by = CASE WHEN c.removed_at IS NOT NULL THEN 'desktop:' || d.source_install_id::text END,
         removed_kind = CASE WHEN c.removed_at IS NOT NULL THEN 'checklist' END
    FROM public.cloud_deals d
   WHERE d.id = c.cloud_deal_id AND c.created_by_kind IS NULL;
  UPDATE public.cloud_deal_checklist_items t
     SET created_by_kind = 'desktop', created_by_ref = d.source_install_id::text,
         done_eff_at = coalesce(t.source_updated_at, t.updated_at), done_by = 'desktop:' || d.source_install_id::text,
         title_eff_at = coalesce(t.source_updated_at, t.updated_at), title_by = 'desktop:' || d.source_install_id::text,
         note_eff_at = coalesce(t.source_updated_at, t.updated_at), note_by = 'desktop:' || d.source_install_id::text,
         due_eff_at = coalesce(t.source_updated_at, t.updated_at), due_by = 'desktop:' || d.source_install_id::text,
         order_eff_at = coalesce(t.source_updated_at, t.updated_at), order_by = 'desktop:' || d.source_install_id::text,
         removed_eff_at = t.removed_at, removed_by = CASE WHEN t.removed_at IS NOT NULL THEN 'desktop:' || d.source_install_id::text END,
         removed_kind = CASE WHEN t.removed_at IS NOT NULL THEN 'item' END
    FROM public.cloud_deals d
   WHERE d.id = t.cloud_deal_id AND t.created_by_kind IS NULL;
  IF ((SELECT count(*) FROM public.cloud_deals WHERE change_seq IS NULL)
         + (SELECT count(*) FROM public.cloud_deal_checklists WHERE change_seq IS NULL)
         + (SELECT count(*) FROM public.cloud_deal_checklist_items WHERE change_seq IS NULL)) <> 0 THEN
    RAISE EXCEPTION 'BACKLOG-4263 PR-4a: unnumbered rows remain';
  END IF;
END
$backfill4263a$;

-- ============================================================================ 2. rows the one-way tombstone scrubbed
-- Their signature: removed, not purged, and scrubbed the way only the one-way cloud_tombstone scrubbed
-- (items: links '[]', written by no other function except the purge, which also sets purged_at; checklists:
-- template_name NULL, which neither the desktop create nor the AI-app My items create writes).
DO $scrubbed4263a$
DECLARE v_id uuid; v_owner uuid;
BEGIN
  FOR v_id, v_owner IN SELECT t.id, t.owner_user_id FROM public.cloud_deal_checklist_items t
                        WHERE t.removed_at IS NOT NULL AND t.purged_at IS NULL AND t.links = '[]'::jsonb      /*SCRUB:items*/
                        ORDER BY t.owner_user_id, t.id LOOP
    UPDATE public.cloud_deal_checklist_items SET purged_at = now(), change_seq = (public._cloud_todo_take_seq(v_owner, 1))[1]
     WHERE id = v_id;
  END LOOP;
  FOR v_id, v_owner IN SELECT c.id, c.owner_user_id FROM public.cloud_deal_checklists c
                        WHERE c.removed_at IS NOT NULL AND c.purged_at IS NULL AND c.template_name IS NULL     /*SCRUB:checklists*/
                        ORDER BY c.owner_user_id, c.id LOOP
    UPDATE public.cloud_deal_checklists SET purged_at = now(), change_seq = (public._cloud_todo_take_seq(v_owner, 1))[1]
     WHERE id = v_id;
  END LOOP;
END
$scrubbed4263a$;

-- ============================================================================ 3. the one-way checklist and item upserts
DROP FUNCTION IF EXISTS public.cloud_upsert_checklists(uuid, uuid, uuid, jsonb);
DROP FUNCTION IF EXISTS public.cloud_upsert_checklist_items(uuid, uuid, uuid, jsonb);

-- ============================================================================ 4. replaced without the checklist kinds
CREATE OR REPLACE FUNCTION public.cloud_tombstone(p_expected_user_id uuid, p_source_install_id uuid, p_kind text, p_cloud_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $f$
/*BODY:4263-4a*/
DECLARE v_uid uuid := auth.uid(); v_tab text; v_id uuid; out jsonb := '[]'::jsonb;
        v_row_id uuid; v_row_deal uuid; v_row_removed timestamptz; v_row_version bigint; v_blob uuid; v_deals uuid[];
        v_fence uuid[] := '{}'; v_now timestamptz;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authorized'); END IF;
  IF p_expected_user_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'wrong_account'); END IF;   /*WHO:tombstone*/
  -- checklists and items are todo changes (cloud_todo_push) since 20261118120000: no arm for them here
  v_tab := CASE p_kind WHEN 'party' THEN 'cloud_deal_parties' WHEN 'message' THEN 'cloud_deal_messages'
                       WHEN 'file' THEN 'cloud_deal_files' END;
  IF v_tab IS NULL OR p_source_install_id IS NULL OR p_cloud_ids IS NULL OR cardinality(p_cloud_ids) > 1000 THEN   /*CAP:tombstone*/
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_input');
  END IF;
  PERFORM 1 FROM public.cloud_autosave_settings WHERE user_id = v_uid FOR SHARE;
  IF public._cloud_install_removed(v_uid, p_source_install_id) THEN                       /*GATE:install:tombstone*/
    RETURN jsonb_build_object('ok', false, 'error', 'install_removed');
  END IF;
  EXECUTE format(
    'SELECT array_agg(x.id) FROM (SELECT d.id FROM public.cloud_deals d
       WHERE d.owner_user_id = $1 AND d.source_install_id = $2
         AND d.id IN (SELECT t.cloud_deal_id FROM public.%I t WHERE t.id = ANY ($3) AND t.owner_user_id = $1)
       ORDER BY d.id FOR NO KEY UPDATE) x', v_tab)
    INTO v_deals USING v_uid, p_source_install_id, p_cloud_ids;                              /*TOMB:lockdeals*/
  v_now := clock_timestamp();                                                                /*CLOCK:tombstone*/
  FOREACH v_id IN ARRAY p_cloud_ids LOOP
    v_row_id := NULL;
    EXECUTE format(
      'SELECT t.id, t.cloud_deal_id, t.removed_at, t.version FROM public.%I t
         JOIN public.cloud_deals d ON d.id = t.cloud_deal_id
        WHERE t.id = $1 AND t.owner_user_id = $2 /*OWNER:tombstone*/
          AND d.source_install_id = $3 /*INSTALL:tombstone*/
        FOR UPDATE OF t', v_tab)
      INTO v_row_id, v_row_deal, v_row_removed, v_row_version USING v_id, v_uid, p_source_install_id;
    IF v_row_id IS NULL THEN
      out := out || jsonb_build_object('cloud_id', v_id, 'status', 'not_found');
      CONTINUE;
    END IF;
    IF v_row_removed IS NOT NULL THEN
      out := out || jsonb_build_object('cloud_id', v_id, 'status', 'unchanged', 'version', v_row_version);
      CONTINUE;
    END IF;
    IF p_kind = 'party' THEN
      UPDATE public.cloud_deal_parties SET removed_at = now(), version = version + 1, updated_at = now(),
             display_name = NULL, company = NULL, emails = NULL, phones = NULL, notes = NULL
       WHERE id = v_row_id RETURNING version INTO v_row_version;
    ELSIF p_kind = 'message' THEN
      UPDATE public.cloud_deal_messages SET removed_at = now(), version = version + 1, updated_at = now(),
             subject = NULL, body_text = NULL, body_truncated = false, participants = NULL          /*TOMB:scrub*/
       WHERE id = v_row_id RETURNING version INTO v_row_version;
    ELSE
      SELECT f.blob_id INTO v_blob FROM public.cloud_deal_files f WHERE f.id = v_row_id;
      UPDATE public.cloud_deal_files f SET removed_at = now(), version = version + 1, updated_at = now(),
             filename = NULL, blob_id = NULL
       WHERE f.id = v_row_id RETURNING f.version INTO v_row_version;
      v_fence := v_fence || v_blob;
    END IF;
    UPDATE public.cloud_deals SET last_synced_at = greatest(last_synced_at, v_now) WHERE id = v_row_deal;
    out := out || jsonb_build_object('cloud_id', v_id, 'status', 'removed', 'version', v_row_version);
  END LOOP;
  PERFORM public._cloud_fence_unreferenced(v_uid, v_fence);                                  /*TOMB:fence*/
  RETURN jsonb_build_object('ok', true, 'results', out);
END $f$;
REVOKE ALL ON FUNCTION public.cloud_tombstone(uuid, uuid, text, uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.cloud_tombstone(uuid, uuid, text, uuid[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.cloud_list_install_rows(
  p_expected_user_id uuid, p_source_install_id uuid, p_kind text, p_after uuid, p_limit integer
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $f$
/*BODY:4263-4a*/
DECLARE v_uid uuid := auth.uid(); v_limit integer; v_tab text; v_local text; v_deal text; v_removed text;
        v_rows jsonb; v_n integer; v_last uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authorized'); END IF;
  IF p_expected_user_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'wrong_account'); END IF;   /*WHO:list_rows*/
  IF p_source_install_id IS NULL OR p_kind IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_input'); END IF;
  SELECT k.tab, k.local_col, k.deal_col, k.removed_expr INTO v_tab, v_local, v_deal, v_removed
    FROM (VALUES
      ('deal',           'cloud_deals',                'local_transaction_id', 't.id',            't.removed_at IS NOT NULL'),
      ('party',          'cloud_deal_parties',         'local_party_id',       't.cloud_deal_id', 't.removed_at IS NOT NULL OR d.removed_at IS NOT NULL')
    ) k(kind, tab, local_col, deal_col, removed_expr)                                          -- no checklist kinds since 20261118120000                                           /*LIVE:list_rows*/
   WHERE k.kind = p_kind;
  IF v_tab IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_input'); END IF;
  v_limit := least(greatest(coalesce(p_limit, 1000), 1), 1000);                               /*CAP:list_rows*/
  EXECUTE format(
    'SELECT coalesce(jsonb_agg(jsonb_build_object(''cloud_id'', x.id, ''cloud_deal_id'', x.deal_id, ''local_id'', x.local_id,
                                                   ''content_hash'', x.content_hash, ''removed'', x.removed) ORDER BY x.id), ''[]''::jsonb),
            count(*)::integer, (array_agg(x.id ORDER BY x.id DESC))[1]
       FROM (SELECT t.id, %s AS deal_id, t.%I AS local_id, t.content_hash, (%s) AS removed
               FROM public.%I t JOIN public.cloud_deals d ON d.id = %s
              WHERE t.owner_user_id = $1 AND d.owner_user_id = $1 /*OWNER:list_rows*/
                AND d.source_install_id = $2 /*INSTALL:list_rows*/
                AND ($3 IS NULL OR t.id > $3)
              ORDER BY t.id LIMIT $4) x',
    v_deal, v_local, v_removed, v_tab, v_deal)
    INTO v_rows, v_n, v_last USING v_uid, p_source_install_id, p_after, v_limit;
  RETURN jsonb_build_object('ok', true, 'rows', v_rows,
                            'next_after', CASE WHEN v_n = v_limit THEN v_last END);
END $f$;
REVOKE ALL ON FUNCTION public.cloud_list_install_rows(uuid, uuid, text, uuid, integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.cloud_list_install_rows(uuid, uuid, text, uuid, integer) TO authenticated;

DO $rerun$
BEGIN
  PERFORM pg_temp.rec('C12_rerun', pg_temp.pass(NOT EXISTS (SELECT 1 FROM pg_temp.p4263a_md5 x JOIN pg_proc p ON p.oid = to_regprocedure(x.sig) WHERE md5(p.prosrc) <> x.m), 'bodies changed on re-run'));
END $rerun$;
DO $fin4263a$ BEGIN RAISE EXCEPTION 'P4263A_RESULT %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.p4263a_out); END $fin4263a$;
